from pwn import remote
import re

def parse_var_lines(sock):
    vars = {}
    while True:
        line = sock.recvline(timeout=3).decode()
        if 'N =' in line:
            vars['N'] = int(line.split('=')[1].strip())
        elif 'G =' in line:
            vars['G'] = int(line.split('=')[1].strip())
        elif 'publ =' in line:
            vars['publ'] = int(line.split('=')[1].strip())
        elif 'alice =' in line:
            vars['alice'] = int(line.split('=')[1].strip())
        elif 'nbits =' in line:
            vars['nbits'] = int(line.split('=')[1].strip())
        elif 'FLAG =' in line:
            vars['FLAG'] = line.split('=')[1].strip()
            break
    return vars

def main():
    HOST, PORT = "crypto.chal.csaw.io", 5000
    s = remote(HOST, PORT)
    vals = parse_var_lines(s)
    print("[+] Parsed values:")
    for k in vals:
        print(f"{k}: {vals[k]}")
    # Oracle - send publ as query
    query = str(vals['publ'])
    s.sendline(query.encode())
    response = s.recvline(timeout=3).decode()
    leakbit = int(response.strip())
    print(f"[+] Oracle response for publ: {leakbit}")
    s.close()
    # Output all as dict for future extension
    result = vals.copy()
    result['oracle_bit'] = leakbit
    print("[+] Final parsed result:")
    for k, v in result.items():
        print(f"{k}: {v}")

if __name__ == '__main__':
    main()

